// Destiny 1 gear lighting for three.js, from the game's own light shaders (e.g. ps 80aa9d72, ps4_globals_0154).
//
// The engine lights the G-buffer with a 2D BRDF table (texture 80ae4219, 32 x 160, R16G16 float, in
// client_bootstrap): u = sqrt(1 - N.H), v = floor(row * 10.6458) * 0.1 + gloss * 0.09375 + 0.00328 (10 material
// rows x 16 gloss steps). Per light: diffuse = N.L * table.g * colour, specular = N.L * table.r * colour.
// Gear shaders write the row parameter (0.55 bare metal / ~0 dyed paint) and gloss; the exporter stores them in
// the ORM texture (R = row parameter, G = 1 - gloss; R = 1 means "not game-baked": standard PBR is kept).
// The gear shaders' environment-cube reflection is added per pixel from the game's own cubes (see ENV below); three's
// own indirect specular is skipped on those texels.
import * as THREE from "three";

const LUT_B64 = "";
let lutTex = null;
export function brdfLut() {
  if (lutTex) return lutTex;
  const bin = atob(LUT_B64), bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const f32 = new Float32Array(bytes.buffer);
  const half = new Uint16Array(f32.length);
  for (let i = 0; i < f32.length; i++) half[i] = THREE.DataUtils.toHalfFloat(f32[i]);
  lutTex = new THREE.DataTexture(half, 32, 160, THREE.RGFormat, THREE.HalfFloatType);
  lutTex.magFilter = lutTex.minFilter = THREE.LinearFilter;
  lutTex.wrapS = lutTex.wrapT = THREE.ClampToEdgeWrapping;
  lutTex.needsUpdate = true;
  return lutTex;
}

export const D1 = { spec: 1.0, diffuse: 1.0, env: 1.0, map: 0 };  // live-tunable scales (uniforms read every frame)

// Game environment cubes (tools/env_atlas.py): each atlas row is one mip, 6 faces (+X -X +Y -Y +Z -Z) side by side.
// The gear shaders sample them per pixel along the reflection vector at their own mip level and add
// tint * sample to the surface colour they write (G-buffer, 8-bit: clamped to 1). The exporter stores that tint in
// the material's occlusion texture (rgb = sqrt(tint / scale), alpha = cube id * 64) and the mip level in ORM blue / 8.
const ENV = [null, { file: "env_80a7451f.png", size: 128 }, { file: "env_80a0856c.png", size: 64 }];
function envTex(i) {
  const e = ENV[i];
  if (!e.tex) {
    e.tex = new THREE.TextureLoader().load(e.file);
    e.tex.flipY = false;
    e.tex.colorSpace = THREE.SRGBColorSpace;
    e.tex.generateMipmaps = false;
    e.tex.minFilter = e.tex.magFilter = THREE.LinearFilter;
    e.tex.wrapS = e.tex.wrapT = THREE.ClampToEdgeWrapping;
  }
  return e.tex;
}
const CUBE_GLSL = `
vec3 d1CubeLevel(sampler2D at, float S, float m, vec3 d) {
  vec3 a = abs(d); float face; vec2 st; float ma;
  if (a.x >= a.y && a.x >= a.z) { ma = a.x; face = d.x > 0.0 ? 0.0 : 1.0; st = vec2(d.x > 0.0 ? -d.z : d.z, -d.y); }
  else if (a.y >= a.z) { ma = a.y; face = d.y > 0.0 ? 2.0 : 3.0; st = vec2(d.x, d.y > 0.0 ? d.z : -d.z); }
  else { ma = a.z; face = d.z > 0.0 ? 4.0 : 5.0; st = vec2(d.z > 0.0 ? d.x : -d.x, -d.y); }
  float s = max(1.0, S / exp2(m));
  vec2 uv = clamp((st / ma + 1.0) * 0.5, 0.5 / s, 1.0 - 0.5 / s);
  float levels = log2(S) + 1.0;
  float H = 2.0 * S * (1.0 - 1.0 / exp2(levels));
  vec2 px = vec2((face + uv.x) * s, 2.0 * S * (1.0 - 1.0 / exp2(m)) + uv.y * s);
  return texture2D(at, px / vec2(6.0 * S, H)).rgb;
}
vec3 d1Cube(sampler2D at, float S, vec3 d, float lod) {
  float top = log2(S);
  lod = clamp(lod, 0.0, top);
  float m0 = floor(lod);
  return mix(d1CubeLevel(at, S, m0, d), d1CubeLevel(at, S, min(m0 + 1.0, top), d), lod - m0);
}`;

export function applyD1Lighting(m) {
  if (!m.isMeshStandardMaterial || m.transparent || !m.roughnessMap || m.userData.d1) return;
  m.userData.d1 = true;
  m.metalness = 1.0;  // metal per pixel from the ORM blue (0 on game-baked texels)
  m.onBeforeCompile = (sh) => {
    sh.uniforms.d1Lut = { value: brdfLut() };
    sh.uniforms.d1Spec = { get value() { return D1.spec; } };
    sh.uniforms.d1Diff = { get value() { return D1.diffuse; } };
    const env = !!(m.userData.d1Env && m.aoMap);
    if (env) {
      sh.uniforms.d1EnvA = { value: envTex(1) };
      sh.uniforms.d1EnvB = { value: envTex(2) };
      sh.uniforms.d1EnvScale = { get value() { return D1.env; } };
      sh.uniforms.d1TintScale = { value: m.userData.d1EnvTintScale || 4.0 };
      sh.uniforms.d1Map = { get value() { return D1.map; } };
      sh.fragmentShader = sh.fragmentShader
        .replace("#include <aomap_fragment>", "")  // the occlusion slot carries the env tint, not AO
        .replace("#include <emissivemap_fragment>", `{
  vec4 d1e = texture2D(aoMap, vAoMapUv);
  float d1id = floor(d1e.a * 255.0 / 64.0 + 0.5);
  if (d1Game && d1id > 0.5) {
    vec3 d1t = d1e.rgb * d1e.rgb * d1TintScale;
    vec3 d1r = inverseTransformDirection(reflect(-normalize(vViewPosition), normal), viewMatrix);
    vec3 d1g = vec3(d1r.x, -d1r.z, d1r.y);  // glTF Y-up -> game Z-up
    if (d1Map == 1) d1g = d1r; else if (d1Map == 2) d1g = vec3(d1r.x, d1r.z, -d1r.y); else if (d1Map == 3) d1g = vec3(-d1r.x, -d1r.z, d1r.y);
    else if (d1Map == 4) d1g = vec3(d1r.z, d1r.x, d1r.y); else if (d1Map == 5) d1g = vec3(d1r.x, -d1r.y, d1r.z);
    float d1lod = texture2D(roughnessMap, vRoughnessMapUv).b * 8.0;
    vec3 d1s = d1id < 1.5 ? d1Cube(d1EnvA, 128.0, d1g, d1lod) : d1Cube(d1EnvB, 64.0, d1g, d1lod);
    diffuseColor.rgb = min(diffuseColor.rgb + d1t * d1s * d1EnvScale, vec3(1.0));
  }
}
#include <emissivemap_fragment>`)
        .replace("#include <lights_physical_pars_fragment>", `#include <lights_physical_pars_fragment>
uniform sampler2D d1EnvA; uniform sampler2D d1EnvB; uniform float d1EnvScale; uniform float d1TintScale; uniform int d1Map;${CUBE_GLSL}`);
    }
    sh.fragmentShader = sh.fragmentShader
      .replace("#include <lights_physical_pars_fragment>", `#include <lights_physical_pars_fragment>
uniform sampler2D d1Lut; uniform float d1Spec; uniform float d1Diff;
float d1Row = 1.0; float d1Gloss = 0.0; bool d1Game = false;
void RE_Direct_D1(const in IncidentLight directLight, const in vec3 geometryPosition, const in vec3 geometryNormal,
                  const in vec3 geometryViewDir, const in vec3 geometryClearcoatNormal, const in PhysicalMaterial material,
                  inout ReflectedLight reflectedLight) {
  if (!d1Game) { RE_Direct_Physical(directLight, geometryPosition, geometryNormal, geometryViewDir, geometryClearcoatNormal, material, reflectedLight); return; }
  float NdotL = saturate(dot(geometryNormal, directLight.direction));
  vec3 H = normalize(directLight.direction + geometryViewDir);
  float u = sqrt(saturate(1.0 - saturate(dot(geometryNormal, H))));
  float v = floor(d1Row * 10.6458) * 0.0999756 + d1Gloss * 0.09375 + 0.00328125;
  vec2 t = texture2D(d1Lut, vec2(u, v)).rg;
  vec3 irr = NdotL * directLight.color;
  reflectedLight.directDiffuse += irr * t.g * material.diffuseColor * d1Diff;
  reflectedLight.directSpecular += irr * t.r * d1Spec;
}
void RE_IndirectSpecular_D1(const in vec3 radiance, const in vec3 irradiance, const in vec3 clearcoatRadiance,
                            const in vec3 geometryPosition, const in vec3 geometryNormal, const in vec3 geometryViewDir,
                            const in vec3 geometryClearcoatNormal, const in PhysicalMaterial material, inout ReflectedLight reflectedLight) {
  if (d1Game) return;
  RE_IndirectSpecular_Physical(radiance, irradiance, clearcoatRadiance, geometryPosition, geometryNormal, geometryViewDir, geometryClearcoatNormal, material, reflectedLight);
}
#undef RE_Direct
#define RE_Direct RE_Direct_D1
#undef RE_IndirectSpecular
#define RE_IndirectSpecular RE_IndirectSpecular_D1`)
      .replace("#include <roughnessmap_fragment>", `#include <roughnessmap_fragment>
{ vec4 d1orm = texture2D(roughnessMap, vRoughnessMapUv); d1Game = d1orm.r < 0.98; d1Row = d1orm.r; d1Gloss = 1.0 - d1orm.g; }`)
      .replace("#include <metalnessmap_fragment>", `#include <metalnessmap_fragment>
if (d1Game) metalnessFactor = 0.0;  // ORM blue holds the env mip level on game texels, not metal`);
  };
  m.needsUpdate = true;
}

// Game glow passes (export: glow_* materials, additive). Swords' energy shaders scale their glow by the view angle;
// the exporter samples that curve from the game shader as userData.d1ViewLut (33 values over N.V in [-1, 1]) and it
// is applied here per pixel, so overlapping layers fade as in the game.
export function applyD1Glow(m) {
  if (!m.userData.d1Additive || m.userData.d1GlowDone) return;
  m.userData.d1GlowDone = true;
  m.blending = THREE.AdditiveBlending; m.transparent = true; m.depthWrite = false;
  const lut = m.userData.d1ViewLut;
  if (!lut) return;
  m.onBeforeCompile = (sh) => {
    sh.uniforms.d1ViewLut = { value: lut };
    sh.fragmentShader = sh.fragmentShader
      .replace("#include <common>", `#include <common>
uniform float d1ViewLut[33];`)
      .replace("#include <emissivemap_fragment>", `#include <emissivemap_fragment>
{ float d1nv = clamp(dot(normalize(normal), normalize(vViewPosition)), -1.0, 1.0);
  float d1f = (d1nv + 1.0) * 16.0; int d1i = int(min(floor(d1f), 31.0));
  totalEmissiveRadiance *= mix(d1ViewLut[d1i], d1ViewLut[d1i + 1], d1f - float(d1i)); }`);
  };
  m.needsUpdate = true;
}
